/// Has every row measured again, as when the width changes, for rows that
/// are drawn differently at the same width: the rows in view are laid out
/// anew on the next frame, and the rest a few at a time after it.
pub fn remeasure(&self) {
    let mut heights = self.heights.borrow_mut();
    for row in &mut heights.rows {
        row.exact = false;
    }
    heights.next = 0;
    heights.hint = true;
}

